; Title menu loop: option keys, joystick handedness and fire to start
; $08b1-$09bb

; Title menu loop (state machine of the title screen). Called by show_title_screen; returns when a game
; starts (the caller falls into start_new_game). Each pass:
; - title_countdown (decremented by irq_title_frame) zero: jump to start_attract_demo.
; - a key: F7 starts the game; F3 toggles 1/2 players (option_two_players); F5 toggles computer/human Yamo
;   (option_yamo_player2); L, R, shift-L, shift-R set the joystick handedness and print a message. Each
;   option key restarts the countdown.
; - about 350 frames after the last option key the message row is cleared (message $0E).
; - fire on joystick port 1 starts the game.
; Starting waits until fire is released on both ports, then 16 frames, and returns.
title_menu_loop
        lda title_countdown
        ora title_countdown+1
        bne title_menu_scan_keys
        jmp start_attract_demo          ; countdown expired: attract demo
title_menu_scan_keys
        lda #$00
        sta key_scan_mode               ; key_scan_mode = 0: decode every key
        jsr scan_keyboard               ; key_code / key_ready
        lda key_ready
        beq title_menu_check_message_timeout
        lda #$00
        sta key_ready
        lda key_code
        jmp title_menu_handedness_keys  ; L / R keys first
title_menu_function_keys
        and #$7f                        ; ignore shift
        cmp #$03                        ; F7: start the game
        beq title_menu_start_game
        cmp #$06                        ; F5: computer / human opponent
        beq title_menu_toggle_opponent
        cmp #$05                        ; F3: one / two players
        beq title_menu_toggle_players
title_menu_check_message_timeout
        lda title_countdown+1           ; countdown at $08xx with low byte 0-1: about 350 frames after the reset
        cmp #$08
        bne title_menu_check_fire
        lda title_countdown
        cmp #$02
        bcs title_menu_check_fire
        lda #$0e                        ; string $0E (36 spaces) at double row 10, column 2: clear the message
        ldx #$0a
        ldy #$02
        jsr print_message
title_menu_check_fire
        lda CIAPRB                      ; joystick port 1 fire (bit 4 = 0 when pressed)
        and #$10
        bne title_menu_loop
title_menu_start_game
        jsr wait_fire_released
        lda #$10                        ; wait 16 frames
        sta frame_countdown
title_menu_wait_start_delay
        lda frame_countdown
        bne title_menu_wait_start_delay
        rts
; F5: toggle the opponent option (computer Yamo / Yamo played by player 2).
title_menu_toggle_opponent
        lda option_yamo_player2
        eor #$01                        ; 0 = computer Yamo, 1 = player 2 controls Yamo
        sta option_yamo_player2
        sta option_yamo_player2_saved
        jsr title_show_opponent_choice  ; toggle the opponent highlight
; After an option key: wait for fire release, restart the 2400-frame countdown, wait 4 frames.
title_menu_option_changed
        jsr wait_fire_released
        lda #$09
        sta title_countdown+1
        lda #$60
        sta title_countdown
        lda #$04
        sta frame_countdown
title_menu_wait_option_delay
        lda frame_countdown
        bne title_menu_wait_option_delay
        jmp title_menu_loop
; F3: toggle the players option, then the steps of title_menu_option_changed inline.
title_menu_toggle_players
        lda option_two_players
        eor #$01                        ; 0 = one player, 1 = two players
        sta option_two_players
        sta option_two_players_saved
        jsr title_show_players_choice   ; toggle the players highlight
        jsr wait_fire_released
        lda #$09
        sta title_countdown+1
        lda #$60
        sta title_countdown
        lda #$04
        sta frame_countdown
        bne title_menu_wait_option_delay ; always taken
; Wait until the fire buttons of both joysticks are released (bit 4 of CIAPRA and CIAPRB both 1). Changes
; A. Called by title_menu_loop and by check_demo_abort (demo_abort_to_title).
wait_fire_released
        lda CIAPRA
        and CIAPRB
        and #$10
        beq wait_fire_released
        rts
; Handedness keys. Input: A = key code. L ($2A) and R ($11, matrix column 2 row 1; D would be $12) set joystick 1
; (joystick_right_handed), shift-L ($AA) and shift-R ($91) set joystick 2 (joystick_right_handed+1): 0 = left-handed,
; 1 = right-handed (the default). Each prints its message (8, 9, $0A, $0D) at double row 10, column 2, then goes to
; title_menu_option_changed. Other keys go to title_menu_function_keys.
title_menu_handedness_keys
        cmp #$2a
        beq title_set_joy1_left_handed
        cmp #$aa
        beq title_set_joy2_left_handed
        cmp #$11
        beq title_set_joy1_right_handed
        cmp #$91
        beq title_set_joy2_right_handed
        jmp title_menu_function_keys
title_set_joy1_left_handed
        lda #$08                        ; "JOYSTICK # 1 IS IN LEFT HANDED MODE"
        ldx #$0a
        ldy #$02
        jsr print_message
        lda #$00
        sta joystick_right_handed       ; joystick 1: left handed
        beq title_handedness_done
title_set_joy2_left_handed
        lda #$0a                        ; "JOYSTICK # 2 IS IN LEFT HANDED MODE"
        tax
        ldy #$02
        jsr print_message
        lda #$00
        sta joystick_right_handed+1     ; joystick 2: left handed
        beq title_handedness_done
title_set_joy1_right_handed
        lda #$09                        ; "JOYSTICK # 1 IS IN RIGHT HANDED MODE"
        ldx #$0a
        ldy #$02
        jsr print_message
        lda #$01
        sta joystick_right_handed       ; joystick 1: right handed
        bne title_handedness_done
title_set_joy2_right_handed
        lda #$0d                        ; "JOYSTICK # 2 IS IN RIGHT HANDED MODE"
        ldx #$0a
        ldy #$02
        jsr print_message
        lda #$01
        sta joystick_right_handed+1     ; joystick 2: right handed
title_handedness_done
        jmp title_menu_option_changed
; Fill all of colour RAM ($D800-$DBFF) with A. Changes X (0 on return).
fill_colour_ram
        ldx #$00
fill_colour_ram_loop
        sta $d800,x
        sta $d900,x
        sta $da00,x
        sta $db00,x
        inx
        bne fill_colour_ram_loop
        rts
; Title tune counter. show_title_screen decrements it and plays the tune when it goes below zero, then sets
; it to 4. 0 at load; lose_fall sets 0 when the demo ends, and the S key (handle_game_keys_check_s) sets 0.
title_music_skip_count
        !byte $00
